import ast,json,subprocess
from pathlib import Path
root=Path('/workspace')
runtime=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
p=json.loads((root/'proposal.json').read_text())
def validate(value,schema,path):
    typ=schema.get('type')
    types={'object':dict,'array':list,'string':str,'boolean':bool}
    if typ in types: assert isinstance(value,types[typ]),(path,'type',typ)
    if 'const' in schema: assert value==schema['const'],(path,'const')
    if 'enum' in schema: assert value in schema['enum'],(path,'enum')
    if isinstance(value,dict):
        assert set(schema.get('required',[]))<=set(value),(path,'required')
        props=schema.get('properties',{})
        if schema.get('additionalProperties') is False: assert set(value)<=set(props),(path,'extra')
        for key,item in value.items():
            if key in props: validate(item,props[key],path+'.'+key)
    elif isinstance(value,list):
        assert len(value)>=schema.get('minItems',0),(path,'minItems')
        for i,item in enumerate(value): validate(item,schema.get('items',{}),path+f'[{i}]')
    elif isinstance(value,str): assert len(value)>=schema.get('minLength',0),(path,'minLength')
validate(p['study'],runtime['study_schema'],'study')
assert p['study']['protocol_ref']==runtime['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(runtime['context']['allowed_observation_ids'])
assert p['parent_trial'] in runtime['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
assert len(set(v['name'] for v in p['variants']))==len(p['variants'])
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
def methods(tree):
    cls=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
    return {n.name:ast.dump(n,include_attributes=False) for n in cls.body if isinstance(n,ast.FunctionDef)}
parent=ast.parse((root/'history_g0_r0002_attention_time.py').read_text())
pm=methods(parent)
configs=[];trees=[]
for v in p['variants']:
    assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
    source=(root/v['file']).read_text()
    tree=ast.parse(source)
    compile(tree,v['file'],'exec')
    for n in ast.walk(tree):
        if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed for a in n.names)
        if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed
        if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','eval','exec','__import__','compile'}
    cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
    assert cfg==v['config']
    for name in ['_evidence','_select_evidence','forward']:
        assert methods(tree)[name]==pm[name],(v['name'],'changed inherited '+name)
    configs.append(cfg);trees.append(tree)
base=[ast.dump(n,include_attributes=False) for n in trees[0].body if not (isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))]
for t in trees[1:]:
    other=[ast.dump(n,include_attributes=False) for n in t.body if not (isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='CONFIG' for x in n.targets))]
    assert base==other,'Cells differ beyond literal config'
assert {(c['use_match_gate'],c['use_learned_scores']) for c in configs}=={(False,False),(False,True),(True,False),(True,True)}
# Compare parent scoring expressions to the learned branch, modulo the
# intentional eligibility variable rename. Other inherited methods equal ASTs.
parent_cls=next(n for n in parent.body if isinstance(n,ast.ClassDef))
parent_summary=next(n for n in parent_cls.body if isinstance(n,ast.FunctionDef) and n.name=='_summary')
new_cls=next(n for n in trees[0].body if isinstance(n,ast.ClassDef))
new_summary=next(n for n in new_cls.body if isinstance(n,ast.FunctionDef) and n.name=='_summary')
branch=next(n for n in new_summary.body if isinstance(n,ast.If))
class RenameMask(ast.NodeTransformer):
    def visit_Name(self,node):
        if node.id=='eligible': node.id='mask'
        return node
new_branch=[ast.dump(RenameMask().visit(n),include_attributes=False) for n in branch.body]
old_start=next(i for i,n in enumerate(parent_summary.body) if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='query' for t in n.targets))
assert new_branch==[ast.dump(n,include_attributes=False) for n in parent_summary.body[old_start:-1]],'Learned scoring expression changed'
assert ast.dump(parent_summary.body[-1],include_attributes=False)==ast.dump(new_summary.body[-1],include_attributes=False)
print('PASS: study schema, protocol, evidence IDs, parent, variant configurations, four factorial cells, restricted imports, standalone syntax, identical variant ASTs except CONFIG, unchanged inherited evidence/forward, and unchanged learned-score arithmetic.')
print('LIMITATION: torch is unavailable by runtime contract; tensor execution, gradients, optimizer steps, reproducibility metrics and costs require host validation.')
print('FILES:', ', '.join(v['file'] for v in p['variants'])+', proposal.json')
PY"

